 if(year>=190){examples[0].status='competing';examples[0].faction='鄰近郡府（示例競爭勢力）';}
 // Source-mentioned historical actors are tracked separately from the playable sample roster.
 void persons;
 const model:Phase4Model={version:1,contentVersion,day:0,year,month,dayOfMonth:1,nodes,causes:[...new Set(['dong-zhuo-central-control','regional-arms-resistance','campaign-risk','local-office-vacancy',...visibleContent.filter(content=>content.introducedRevision).flatMap(contentCauses)])],historicalPersons:historicalPeople,playerLocation:'家宅・庭院',medicalSupplies:1,territories:[{id:'sample-county',name:'潁川東部路線・郡縣示例',control:'名義影響',owner:'漢廷名義',population:10000,grain:1000,support:50,policy:null,interests:{gentry:50,farmers:50,merchants:50},example:true},{id:'sample-market',name:'許縣至潁川驛路（示例）',control:'穩定治理',owner:'地方官府',population:2500,grain:300,support:55,policy:'互市與道路',interests:{gentry:45,farmers:50,merchants:60},example:true}],offices,candidates:examples,routes:[{id:'route-county-market',from:'潁川東部路線・郡縣示例',to:'許縣至潁川驛路（示例）',days:ENGINEERING.travelDaysPerRoute,terrain:'平原驛道',risk:5,example:true},{id:'route-market-pass',from:'許縣至潁川驛路（示例）',to:'汝南渡口（示例）',days:4,terrain:'平原與渡口',risk:15,example:true}],convoys:[],battle:null,treaties:[],authorizations:[],policiesLog:[],externalUpdates:year>=190?[`${examples[0].name}已受鄰近郡府延請（示例競爭勢力）。`]:[],unified:false,ending:'continuing',chosenEnding:undefined,eventLedger:[]};
 if(contentVersion!==PHASE4_LEGACY_CONTENT_VERSION){for(const node of model.nodes){const content=nodeContent(node.contentId);if(content.introducedRevision&&year>=content.startYear)processHistoryNode(model,node);}}
