function dateAdd(m:Phase4Model,days:number){for(let i=0;i<days;i++){m.day++;m.dayOfMonth++;if(m.dayOfMonth>30){m.dayOfMonth=1;m.month++;if(m.month>12){m.month=1;m.year++;processYear(m);}} if(m.day%30===0)processMonth(m); finishArrivals(m); processConvoys(m); settleDeaths(m); settleRecruitment(m);}}
function processHistoryNode(m:Phase4Model,node:HistoryNode){const content=nodeContent(node.contentId);if(contentIsRetired(content,m.contentVersion)||node.status!=='pending'||m.year<content.startYear||m.year>content.endYear)return;
 if(content.kind==='death'){node.status='triggered';node.triggeredDay=m.day;node.resolvedYear=m.year;const windowDays=deathInterventionWindowDays(node.contentId);pushEvent(m,'死亡硬節點觸發',windowDays?`${content.title}開啟 ${windowDays} 個模型日介入窗（本事件可調工程設定）；須實際介入，不以持有能力代替。`:`${content.title}沒有額外介入緩衝，於觸發日依事件處理；不可在死亡後補開窗口。`,content.source);}
 else {const causes=contentCauses(content),remaining=causes.filter(c=>m.causes.includes(c));if(remaining.length===0){node.status='cancelled';node.resolvedYear=m.year;pushEvent(m,'史實事件取消',`${content.title}的核心原因已消失，事件不再強行發生。`,content.source);}else{node.status='triggered';node.resolvedYear=m.year;const carrier=remaining.length===causes.length?content.carrier:remaining.map(c=>content.carriersByCause?.[c]).filter((x):x is string=>Boolean(x)).join('、');node.carrier=carrier||content.carrier;pushEvent(m,'史實事件形成',`${content.title}由${node.carrier}承載；核心原因仍存。`,content.source);}}
}
function processYear(m:Phase4Model){if(m.year>=190){const candidate=m.candidates.find(c=>c.status==='available'||c.status==='approached');if(candidate){candidate.status='competing';candidate.faction='鄰近郡府（示例競爭勢力）';m.externalUpdates.push(`${candidate.name}先受鄰近郡府延請；招攬競爭依時間推進。`);}}for(const node of m.nodes)processHistoryNode(m,node);}
